"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[811],{5811:(n,i,t)=>{t.r(i),t.d(i,{default:()=>h});let h={id:"ja",viName:"tiếng Nhật",flag:"\uD83C\uDDEF\uD83C\uDDF5",scriptMode:"cjk",minDialogueChars:0,minBoldWords:1,storagePrefix:"lingua-ja-",defaults:{level:"A1",profile:"everyday"},mascot:{kind:"owl",badge:"\uD83E\uDD89 Linh vật"},nameEn:"Japanese",nameNative:"日本語",appTitle:"Teacher AI — Học tiếng Nhật c\xf9ng AI",appDescription:"Luyện giao tiếp tiếng Nhật c\xf9ng gia sư AI, d\xe0nh cho người Việt.",shortName:"Teacher AI",speechLang:"ja-JP",langPrefix:"ja",levelSystem:"JLPT",levelLabels:{A1:"N5",A2:"N4",B1:"N3",B2:"N2"},phoneticName:"romaji",targetScript:/[぀-ヿ㐀-鿿ｦ-ﾟ]/,targetRun:/[぀-ヿ㐀-鿿ｦ-ﾟ][぀-ヿ㐀-鿿ｦ-ﾟ　-〿＀-･ー・\s、。！？!?,.]*/g,sentenceEnd:"。！？",recognitionHint:"N\xf3i bằng tiếng Nhật",welcome:{headline:"Xin ch\xe0o! C\xf9ng n\xf3i tiếng Nhật tự tin hơn nh\xe9.",greeting:"こんにちは!"},pronunciationFocus:"long vs short vowels (おばさん / おばあさん), small っ (double consonants), ん, pitch accent, the ら row, voiced vs unvoiced consonants (か / が, た / だ), ふ, つ, じ / ず",promptNotes:'Teaching language: Japanese (日本語). Level system: JLPT (N5 = A1, N4 = A2, N3 = B1, N2 = B2).\n- Write every Japanese sentence the learner should say inside double quotes "…", and IMMEDIATELY after it give its romaji in square brackets, e.g. "こんにちは" [konnichiwa]. At N5–N4 always add romaji; at N3–N2 only for new or difficult words. Never write romaji anywhere else. Text in square brackets is never read aloud.\n- Use only kana and the kanji appropriate for the level (N5–N4: mostly hiragana/katakana with basic kanji such as 私, 日本, 学生).\n- Politeness: teach です/ます first; bring in plain form, 敬語 (尊敬語・謙譲語) only from N3, and point out when the learner\'s politeness level does not fit the situation.\n- Typical mistakes of Vietnamese learners to watch for: particle choice (は / が / を / に / で / へ), long vowels, small っ, mixing up ら-row sounds, て-form and ます-form conjugation, counters, topic omission.',pedagogy:{A1:"- Explain mostly in Vietnamese (about 80%). Japanese only in very short model sentences (2–6 words), each followed by its romaji in [brackets] and the Vietnamese meaning.\n- One new item per turn. Tasks: repeat after me, choose A or B, complete one word. Accept one-word answers, then model the full sentence.\n- Use です/ます only. Correct only the most important mistake each turn; be very encouraging.",A2:'- Mix Vietnamese explanations (about 50%) with simple Japanese (N4 grammar: て-form, ない-form, たい, ている, あげる/もらう/くれる). Add romaji in [brackets] to every Japanese sentence.\n- Give a hint like (Gợi \xfd: "〜たいです") for each task. Tasks: full-sentence answers, simple role-plays with 2–3 exchanges.\n- Correct up to two mistakes per turn, mainly particles, conjugation and word choice.',B1:'- Teach mostly in Japanese (about 70%) with natural kanji; give kana readings in [brackets] only for new or difficult kanji words. Use Vietnamese only for tricky grammar or meaning.\n- Role-plays with longer exchanges; ask follow-up "why / how" questions. Introduce plain vs polite form, ようだ/そうだ/らしい, passive and causative basics, 〜ば/〜たら/〜と.\n- Correct every error that affects meaning, plus unnatural particles; offer a more natural phrase.',B2:"- Teach in Japanese; use Vietnamese only if the learner asks. Cover 敬語 (尊敬語・謙譲語), business and written style, idioms, 〜わけではない/〜ざるを得ない-type structures.\n- Discussions, negotiations and problem-solving situations; challenge the learner's opinions. Give readings in [brackets] only for rare kanji.\n- Correct accuracy, register and naturalness, including better word choices."},accents:[{id:"tokyo",group:"Nhật Bản",flag:"\uD83C\uDDEF\uD83C\uDDF5",name:"Tokyo – chuẩn",locales:["ja-jp","ja"],prompt:"a standard Tokyo Japanese",sample:"こんにちは。今日は一緒に日本語を練習しましょう。"},{id:"kansai",group:"Nhật Bản",flag:"\uD83C\uDDEF\uD83C\uDDF5",name:"Kansai – Osaka",locales:["ja-jp","ja"],prompt:"a friendly Kansai (Osaka) Japanese",sample:"おおきに。今日は楽しく日本語を勉強しよか。"}],profiles:[{id:"everyday",title:"Tiếng Nhật giao tiếp hằng ng\xe0y",subtitle:"Ch\xe0o hỏi, mua sắm, ăn uống, nhờ vả",icon:"everyday",color:"yellow",scene:"L\xe0m quen với người mới",prompt:"Xin ch\xe0o! H\xf4m nay ch\xfang ta luyện giao tiếp tiếng Nhật hằng ng\xe0y. C\xf4 sẽ dạy em từng bước nh\xe9.",words:["はじめまして。","よろしくお願いします。","ありがとうございます。"]},{id:"travel",title:"Tiếng Nhật du lịch",subtitle:"Kh\xe1ch sạn, nh\xe0 h\xe0ng, t\xe0u điện, hỏi đường",icon:"travel",color:"orange",scene:"L\xe0m thủ tục nhận ph\xf2ng kh\xe1ch sạn",prompt:"Xin ch\xe0o! H\xf4m nay ch\xfang ta luyện tiếng Nhật khi đi du lịch Nhật Bản. C\xf4 sẽ dạy em từng bước nh\xe9.",words:["予約しています。","トイレはどこですか。","いくらですか。"]},{id:"business",title:"Tiếng Nhật c\xf4ng sở",subtitle:"Họp h\xe0nh, email, điện thoại, b\xe1o c\xe1o",icon:"business",color:"blue",scene:"Trao đổi với đồng nghiệp trong c\xf4ng ty",prompt:"Xin ch\xe0o! H\xf4m nay ch\xfang ta luyện tiếng Nhật c\xf4ng sở. C\xf4 sẽ dạy em từng bước nh\xe9.",words:["お先に失礼します。","承知しました。","確認いたします。"]},{id:"technology",title:"Tiếng Nhật ng\xe0nh c\xf4ng nghệ",subtitle:"Kỹ sư IT, họp, b\xe1o lỗi, phỏng vấn",icon:"technology",color:"purple",scene:"Họp buổi s\xe1ng với nh\xf3m ph\xe1t triển",prompt:"Xin ch\xe0o! H\xf4m nay ch\xfang ta luyện tiếng Nhật ng\xe0nh c\xf4ng nghệ. Thầy/c\xf4 sẽ dạy em từng bước nh\xe9.",words:["バグを修正しました。","テストは完了しました。","仕様を確認させてください。"]},{id:"healthcare",title:"Tiếng Nhật chuy\xean ng\xe0nh y khoa",subtitle:"Điều dưỡng, hộ l\xfd, giao tiếp với bệnh nh\xe2n",icon:"healthcare",color:"green",scene:"Hỏi thăm triệu chứng bệnh nh\xe2n",prompt:"Xin ch\xe0o! H\xf4m nay ch\xfang ta luyện tiếng Nhật chuy\xean ng\xe0nh y khoa. Thầy/c\xf4 sẽ dạy em từng bước nh\xe9.",words:["どこが痛いですか。","お薬を飲みましたか。","少しお待ちください。"]},{id:"finance",title:"Tiếng Nhật ng\xe0nh t\xe0i ch\xednh",subtitle:"Ng\xe2n h\xe0ng, kế to\xe1n, b\xe1o c\xe1o, đầu tư",icon:"finance",color:"pink",scene:"Tr\xecnh b\xe0y b\xe1o c\xe1o t\xe0i ch\xednh th\xe1ng",prompt:"Xin ch\xe0o! H\xf4m nay ch\xfang ta luyện tiếng Nhật ng\xe0nh t\xe0i ch\xednh. Thầy/c\xf4 sẽ dạy em từng bước nh\xe9.",words:["売上が増加しました。","前年比で五パーセントです。","ご確認をお願いします。"]},{id:"refrigeration",title:"Tiếng Nhật kỹ thuật điện lạnh c\xf4ng nghiệp",subtitle:"Kho lạnh, m\xe1y n\xe9n, NH3/CO2, an to\xe0n, bảo tr\xec",icon:"refrigeration",color:"blue",scene:"Nhận y\xeau cầu sửa kho lạnh",prompt:"Xin ch\xe0o! H\xf4m nay ch\xfang ta luyện tiếng Nhật kỹ thuật điện lạnh c\xf4ng nghiệp. Thầy/c\xf4 sẽ dạy em từng bước nh\xe9.",words:["冷凍庫が冷えません。","電源を切ってください。","圧力を確認します。"]}],phraseMeanings:{"はじめまして。":"Rất vui được gặp bạn (lần đầu gặp mặt).","よろしくお願いします。":"Rất mong được gi\xfap đỡ / xin chiếu cố.","ありがとうございます。":"Cảm ơn bạn.","予約しています。":"T\xf4i đ\xe3 đặt chỗ trước.","トイレはどこですか。":"Nh\xe0 vệ sinh ở đ\xe2u ạ?","いくらですか。":"Bao nhi\xeau tiền ạ?","お先に失礼します。":"T\xf4i xin ph\xe9p về trước ạ.","承知しました。":"T\xf4i đ\xe3 hiểu ạ (lịch sự).","確認いたします。":"T\xf4i xin ph\xe9p x\xe1c nhận lại ạ.","バグを修正しました。":"Đ\xe3 sửa lỗi xong.","テストは完了しました。":"Đ\xe3 kiểm thử xong.","仕様を確認させてください。":"Cho ph\xe9p t\xf4i x\xe1c nhận lại đặc tả.","どこが痛いですか。":"B\xe1c đau ở đ\xe2u ạ?","お薬を飲みましたか。":"B\xe1c đ\xe3 uống thuốc chưa ạ?","少しお待ちください。":"Xin chờ một ch\xfat ạ.","売上が増加しました。":"Doanh thu đ\xe3 tăng.","前年比で五パーセントです。":"So với năm trước l\xe0 5%.","ご確認をお願いします。":"Xin qu\xfd vị kiểm tra gi\xfap.","冷凍庫が冷えません。":"Kho đ\xf4ng kh\xf4ng lạnh.","電源を切ってください。":"Xin h\xe3y ngắt nguồn điện.","圧力を確認します。":"T\xf4i sẽ kiểm tra \xe1p suất."},suggestions:{everyday:["はじめまして、ベトナムから来ました。","もう一度ゆっくり言ってください。","C\xf4 giải th\xedch lại bằng tiếng Việt gi\xfap em với.","これはいくらですか。"],travel:["チェックインをお願いします。","駅はどこですか。","C\xf4 hướng dẫn em c\xe1ch ph\xe1t \xe2m c\xe2u vừa rồi nh\xe9.","英語のメニューはありますか。"],business:["お先に失礼します。","会議は何時からですか。","Thầy chỉ ra lỗi ngữ ph\xe1p gi\xfap em nh\xe9.","資料を送っていただけますか。"],technology:["昨日はログイン画面を作りました。","バグの再現手順を説明します。","C\xf4 giải th\xedch lại bằng tiếng Việt gi\xfap em với.","レビューをお願いできますか。"],healthcare:["いつから熱がありますか。","大きく息を吸ってください。","C\xf4 hướng dẫn em c\xe1ch ph\xe1t \xe2m c\xe2u vừa rồi nh\xe9.","心配しないでください。"],finance:["口座を開きたいのですが。","金利はどのくらいですか。","Thầy chỉ ra lỗi ngữ ph\xe1p gi\xfap em nh\xe9.","売上は前年比で増加しました。"],refrigeration:["庫内温度は何度ですか。","膨張弁の詰まりかもしれません。","Thầy giải th\xedch thuật ngữ n\xe0y bằng tiếng Việt nh\xe9.","アンモニアが漏れたら避難します。"]},placement:[{level:"A1",question:"Điền trợ từ: 「わたし___がくせいです。」(T\xf4i l\xe0 sinh vi\xean.)",options:["で","を","は","に"],answer:2,explanation:"は l\xe0 trợ từ chủ đề: 私は〜です."},{level:"A1",question:"「これは何ですか。」—「___はペンです。」",options:["あれ","なに","それ","どれ"],answer:2,explanation:"Hỏi về vật gần người hỏi (これ) → trả lời bằng それ."},{level:"A1",question:"C\xe1ch đọc đ\xfang của 「三時」(3 giờ)?",options:["さんじ","みっつじ","さんとき","みじ"],answer:0,explanation:"三時 = さんじ."},{level:"A1",question:"Điền trợ từ: 「毎日バス___学校へ行きます。」",options:["に","で","が","を"],answer:1,explanation:"で chỉ phương tiện: バスで."},{level:"A1",question:"Điền v\xe0o chỗ trống: 「昨日、映画を___。」(H\xf4m qua t\xf4i đ\xe3 xem phim.)",options:["見ません","見ました","見ます","見る"],answer:1,explanation:"Qu\xe1 khứ lịch sự: 〜ました."},{level:"A2",question:"Điền v\xe0o chỗ trống: 「雨が降っている___、傘を持っていきます。」",options:["から","けど","まで","のに"],answer:0,explanation:"から chỉ l\xfd do: v\xec trời mưa n\xean mang \xf4."},{level:"A2",question:"Điền v\xe0o chỗ trống: 「日本語を話す___ができます。」",options:["こと","ため","ところ","もの"],answer:0,explanation:"V辞書形 + ことができます = c\xf3 thể l\xe0m."},{level:"A2",question:"Điền v\xe0o chỗ trống: 「ここで写真を撮って___いいですか。」",options:["を","も","が","は"],answer:1,explanation:"〜てもいいですか = l\xe0m ~ c\xf3 được kh\xf4ng?"},{level:"A2",question:"Điền v\xe0o chỗ trống: 「先生に日本語を___もらいました。」",options:["教えた","教えて","教える","教え"],answer:1,explanation:"Vてもらう = được ai đ\xf3 l\xe0m cho."},{level:"A2",question:"“Cửa sổ đang mở (tự trạng th\xe1i).” →「窓が___います。」",options:["開け","開いて","開く","開けて"],answer:1,explanation:"Tự động từ 開く + ている chỉ trạng th\xe1i."},{level:"B1",question:"Điền v\xe0o chỗ trống: 「毎日練習した___、上手になりました。」",options:["せいで","おかげで","ために","くせに"],answer:1,explanation:"おかげで: nhờ ~ (kết quả tốt)."},{level:"B1",question:"Điền v\xe0o chỗ trống: 「彼は忙しい___、パーティーに来てくれた。」",options:["から","のに","ので","ために"],answer:1,explanation:"のに: mặc d\xf9 ~ (tr\xe1i với mong đợi)."},{level:"B1",question:"“T\xf4i bị mẹ bắt ăn rau.” →「母に野菜を___。」",options:["食べられた","食べた","食べさせられた","食べさせた"],answer:2,explanation:"Thể sai khiến bị động: 食べさせられる."},{level:"B1",question:"“Tr\xf4ng như sắp mưa.” →「雨が降り___だ。」",options:["らしい","そう","よう","みたい"],answer:1,explanation:"V(bỏ ます) + そうだ: tr\xf4ng như sắp ~."},{level:"B1",question:"Nghĩa của 「予約」?",options:["hủy bỏ","x\xe1c nhận","đặt trước","thanh to\xe1n"],answer:2,explanation:"予約 (よやく) = đặt trước."},{level:"B2",question:"K\xednh ngữ của 来る: 「部長は明日の会議に___。」",options:["いらっしゃいます","伺います","おります","参ります"],answer:0,explanation:"いらっしゃる l\xe0 t\xf4n k\xednh ngữ; 参る, 伺う, おる l\xe0 khi\xeam nhường ngữ."},{level:"B2",question:"Khi\xeam nhường: “T\xf4i sẽ gửi t\xe0i liệu.” →「資料を___。」",options:["お送りになります","送ってくださいます","お送りします","送られます"],answer:2,explanation:"お + V(ます bỏ) + します: khi\xeam nhường ngữ."},{level:"B2",question:"Điền v\xe0o chỗ trống: 「この問題は専門家___解決できない。」",options:["ばかりか","でなければ","からには","だけに"],answer:1,explanation:"〜でなければ〜ない: nếu kh\xf4ng phải ~ th\xec kh\xf4ng ~."},{level:"B2",question:"Từ gần nghĩa nhất với 「検討する」?",options:["決める","すぐ断る","忘れる","よく考える"],answer:3,explanation:"検討する = xem x\xe9t kỹ."},{level:"B2",question:"Điền v\xe0o chỗ trống: 「努力した___、合格できなかった。」",options:["にもかかわらず","ために","からこそ","おかげで"],answer:0,explanation:"にもかかわらず: mặc d\xf9 ~ nhưng."}],tutors:{maya:{name:"Sakura-sensei",title:"C\xf4 gi\xe1o Nhật Bản",tagline:"Dịu d\xe0ng, ph\xe1t \xe2m chuẩn, ki\xean nhẫn hướng dẫn",description:"C\xf4 gi\xe1o nhiệt t\xecnh, sửa tỉ mỉ từng lỗi ph\xe1t \xe2m v\xe0 ngữ ph\xe1p theo tr\xecnh độ của bạn.",greeting:"H\xf4m nay c\xf4 sẽ đồng h\xe0nh c\xf9ng em luyện n\xf3i tiếng Nhật thật tự tin nh\xe9."},david:{name:"Kenji-sensei",title:"Thầy gi\xe1o Nhật Bản",tagline:"Điềm đạm, r\xf5 r\xe0ng, giỏi t\xecnh huống c\xf4ng sở",description:"Thầy gi\xe1o phong c\xe1ch chuy\xean nghiệp, phản xạ nhanh v\xe0 chuy\xean s\xe2u giao tiếp c\xf4ng việc.",greeting:"H\xf4m nay thầy sẽ c\xf9ng em luyện n\xf3i tiếng Nhật thật tự nhi\xean nh\xe9."},alex:{name:"Alex",title:"Linh vật học tập",tagline:"Đ\xe1ng y\xeau, hồn nhi\xean, học tập kh\xf4ng \xe1p lực",description:"Ch\xfa c\xfa th\xf4ng th\xe1i đội mũ tốt nghiệp, vui t\xednh, học tập kh\xf4ng \xe1p lực.",greeting:"C\xf9ng nhau học tiếng Nhật thật vui n\xe0o!"}},grammarTopics:[{id:"wa-desu",level:"A1",title:"C\xe2u giới thiệu: AはBです",structure:"A は B です / A は B ではありません",overview:"は (đọc l\xe0 “wa”) l\xe0 trợ từ chủ đề: n\xeau chủ đề của c\xe2u. です l\xe0 từ nối lịch sự, gần như “l\xe0”. Phủ định lịch sự d\xf9ng ではありません (hoặc じゃありません). C\xe2u hỏi chỉ cần th\xeam か ở cuối, kh\xf4ng đảo trật tự từ.",examples:["私は学生です。[watashi wa gakusei desu] (T\xf4i l\xe0 sinh vi\xean.)","田中さんは先生ではありません。[Tanaka-san wa sensei dewa arimasen] (Anh Tanaka kh\xf4ng phải gi\xe1o vi\xean.)","あなたはベトナム人ですか。[anata wa Betonamu-jin desu ka] (Bạn l\xe0 người Việt Nam phải kh\xf4ng?)"],questions:[{prompt:"Chọn c\xe2u đ\xfang: “T\xf4i l\xe0 kỹ sư.”",options:["私はエンジニアです。","私をエンジニアです。","私にエンジニアです。"],answer:0,explanation:"Chủ đề của c\xe2u đi với は: 私は〜です。"},{prompt:"Điền v\xe0o chỗ trống: 「これは水___ありません。」",options:["では","が","を"],answer:0,explanation:"Phủ định lịch sự của です l\xe0 ではありません."},{prompt:"C\xe1ch đặt c\xe2u hỏi “Bạn l\xe0 người Nhật phải kh\xf4ng?” đ\xfang l\xe0:",options:["あなたは日本人ですか。","あなたは日本人ですの。","あなたか日本人です。"],answer:0,explanation:"Th\xeam か v\xe0o cuối c\xe2u để hỏi; kh\xf4ng đổi trật tự từ."}]},{id:"basic-particles",level:"A1",title:"Trợ từ cơ bản: を・に・で・へ・と",structure:"N を V / N に V / N で V / N へ V / N と V",overview:"を đ\xe1nh dấu t\xe2n ngữ (c\xe1i bị t\xe1c động). に chỉ thời điểm, nơi tồn tại hoặc đ\xedch đến. で chỉ nơi diễn ra h\xe0nh động v\xe0 phương tiện. へ chỉ hướng (đọc l\xe0 “e”). と l\xe0 “v\xe0 / c\xf9ng với”. Chọn sai trợ từ l\xe0 lỗi rất hay gặp của người Việt v\xec tiếng Việt kh\xf4ng c\xf3 trợ từ.",examples:["パンを食べます。[pan o tabemasu] (T\xf4i ăn b\xe1nh m\xec.)","七時に起きます。[shichi-ji ni okimasu] (T\xf4i dậy l\xfac 7 giờ.)","図書館で勉強します。[toshokan de benkyō shimasu] (T\xf4i học ở thư viện.)","友だちと買い物に行きます。[tomodachi to kaimono ni ikimasu] (T\xf4i đi mua sắm với bạn.)"],questions:[{prompt:"Điền v\xe0o chỗ trống: 「コーヒー___飲みます。」",options:["を","に","で"],answer:0,explanation:"T\xe2n ngữ trực tiếp (c\xe1i được uống) d\xf9ng を."},{prompt:"Điền v\xe0o chỗ trống: 「八時___学校へ行きます。」",options:["を","に","と"],answer:1,explanation:"Thời điểm cụ thể (8 giờ) đi với に."},{prompt:"Điền v\xe0o chỗ trống: 「レストラン___晩ごはんを食べます。」",options:["で","に","が"],answer:0,explanation:"で chỉ nơi diễn ra h\xe0nh động (ăn ở nh\xe0 h\xe0ng)."}]},{id:"masu-form",level:"A1",title:"Động từ thể ます: hiện tại, qu\xe1 khứ, phủ định",structure:"V ます / V ません / V ました / V ませんでした",overview:"Thể ます l\xe0 c\xe1ch n\xf3i lịch sự cơ bản. ます d\xf9ng cho hiện tại v\xe0 tương lai; ません l\xe0 phủ định; ました l\xe0 qu\xe1 khứ; ませんでした l\xe0 qu\xe1 khứ phủ định. Động từ tiếng Nhật kh\xf4ng chia theo ng\xf4i hay số, chỉ chia theo thời v\xe0 mức độ lịch sự.",examples:["毎朝コーヒーを飲みます。[maiasa kōhī o nomimasu] (Mỗi s\xe1ng t\xf4i uống c\xe0 ph\xea.)","昨日は学校に行きませんでした。[kinō wa gakkō ni ikimasen deshita] (H\xf4m qua t\xf4i đ\xe3 kh\xf4ng đến trường.)","週末に映画を見ました。[shūmatsu ni eiga o mimashita] (Cuối tuần t\xf4i đ\xe3 xem phim.)"],questions:[{prompt:"“T\xf4i đ\xe3 ăn s\xe1ng.” n\xf3i l\xe0:",options:["朝ごはんを食べました。","朝ごはんを食べます。","朝ごはんを食べません。"],answer:0,explanation:"〜ました l\xe0 qu\xe1 khứ khẳng định."},{prompt:"Dạng phủ định lịch sự của 「行きます」 l\xe0:",options:["行きません","行きました","行かないます"],answer:0,explanation:"〜ます đổi th\xe0nh 〜ません ở dạng phủ định."},{prompt:"“H\xf4m qua t\xf4i kh\xf4ng học.” l\xe0:",options:["昨日は勉強しませんでした。","昨日は勉強しません。","昨日は勉強しなかったます。"],answer:0,explanation:"Qu\xe1 khứ phủ định lịch sự: 〜ませんでした."}]},{id:"adjectives",level:"A1",title:"T\xednh từ い v\xe0 t\xednh từ な",structure:"い-adj: 〜い / 〜くない / 〜かった   な-adj: 〜な N / 〜じゃない / 〜だった",overview:"C\xf3 hai nh\xf3m t\xednh từ. T\xednh từ い kết th\xfac bằng い v\xe0 tự biến đổi (高い → 高くない → 高かった). T\xednh từ な giữ nguy\xean, khi đứng trước danh từ th\xec th\xeam な (きれいな花). Ngoại lệ hay nhầm: いい đổi th\xe0nh よくない / よかった; きれい l\xe0 t\xednh từ な d\xf9 kết th\xfac bằng い.",examples:["この本は高いです。[kono hon wa takai desu] (Quyển s\xe1ch n\xe0y đắt.)","この部屋はきれいです。[kono heya wa kirei desu] (Căn ph\xf2ng n\xe0y sạch đẹp.)","昨日の天気はよくなかったです。[kinō no tenki wa yokunakatta desu] (Thời tiết h\xf4m qua kh\xf4ng tốt.)"],questions:[{prompt:"Dạng phủ định của 「高い」 l\xe0:",options:["高くないです","高いじゃないです","高いくないです"],answer:0,explanation:"T\xednh từ い đổi い th\xe0nh くない."},{prompt:"Chọn c\xe2u đ\xfang: “Đ\xe2y l\xe0 con phố y\xean tĩnh.”",options:["静かな道です。","静かい道です。","静かの道です。"],answer:0,explanation:"静か l\xe0 t\xednh từ な, th\xeam な khi đứng trước danh từ."},{prompt:"Qu\xe1 khứ của 「いいです」 l\xe0:",options:["よかったです","いかったです","いいでした"],answer:0,explanation:"いい l\xe0 bất quy tắc: よかった."}]},{id:"te-form",level:"A2",title:"Thể て: nhờ vả, nối c\xe2u, đang l\xe0m",structure:"V て + ください / V て + V / V ている",overview:"Thể て l\xe0 “ch\xeca kh\xf3a” của ngữ ph\xe1p N4. Gắn ください để nhờ lịch sự, nối hai h\xe0nh động li\xean tiếp, v\xe0 d\xf9ng 〜ている để diễn tả h\xe0nh động đang diễn ra hoặc trạng th\xe1i k\xe9o d\xe0i. C\xe1ch chia て theo nh\xf3m: 〜う・つ・る → って; 〜む・ぶ・ぬ → んで; 〜く → いて; 〜す → して; nh\xf3m 2 bỏ る th\xeam て.",examples:["ここに名前を書いてください。[koko ni namae o kaite kudasai] (Xin h\xe3y viết t\xean v\xe0o đ\xe2y.)","朝起きて、シャワーを浴びます。[asa okite, shawā o abimasu] (Buổi s\xe1ng t\xf4i dậy rồi đi tắm.)","今、電話をしています。[ima, denwa o shite imasu] (B\xe2y giờ t\xf4i đang gọi điện.)"],questions:[{prompt:"Thể て của 「飲む」 l\xe0:",options:["飲んで","飲みて","飲って"],answer:0,explanation:"Động từ kết th\xfac bằng む đổi th\xe0nh んで."},{prompt:"“Xin h\xe3y chờ một ch\xfat.” l\xe0:",options:["ちょっと待ってください。","ちょっと待つください。","ちょっと待ちてください。"],answer:0,explanation:"待つ → 待って (つ → って) + ください."},{prompt:"「彼は今、ご飯を食べています。」 nghĩa l\xe0:",options:["Anh ấy đang ăn cơm.","Anh ấy đ\xe3 ăn cơm rồi.","Anh ấy sẽ ăn cơm."],answer:0,explanation:"〜ている diễn tả h\xe0nh động đang diễn ra."}]},{id:"tai-nai",level:"A2",title:"Muốn l\xe0m g\xec v\xe0 phủ định: 〜たい・〜ない",structure:"V ます bỏ ます + たい / V ない",overview:"〜たい diễn tả mong muốn của ch\xednh người n\xf3i (t\xf4i muốn ~), chia như t\xednh từ い: 食べたい → 食べたくない → 食べたかった. Dạng ない l\xe0 phủ định thể th\xf4ng thường: 行かない, 食べない. C\xf3 hai bất quy tắc: する → しない, 来る → 来ない (こない).",examples:["日本へ行きたいです。[Nihon e ikitai desu] (T\xf4i muốn đi Nhật.)","今日は何も食べたくないです。[kyō wa nani mo tabetakunai desu] (H\xf4m nay t\xf4i kh\xf4ng muốn ăn g\xec.)","明日は学校へ行かない。[ashita wa gakkō e ikanai] (Ng\xe0y mai t\xf4i kh\xf4ng đi học.)"],questions:[{prompt:"“T\xf4i muốn uống nước.” l\xe0:",options:["水が飲みたいです。","水を飲むたいです。","水が飲みいです。"],answer:0,explanation:"Bỏ ます, th\xeam たい: 飲み + たい. T\xe2n ngữ thường d\xf9ng が hoặc を."},{prompt:"Dạng ない của 「来る」 l\xe0:",options:["来ない（こない）","来らない","来ります"],answer:0,explanation:"来る l\xe0 bất quy tắc: こない."},{prompt:"Dạng phủ định của 「食べたい」 l\xe0:",options:["食べたくない","食べたいない","食べなたい"],answer:0,explanation:"たい chia như t\xednh từ い: たい → たくない."}]},{id:"ta-koto-ga-aru",level:"A2",title:"Kinh nghiệm v\xe0 liệt k\xea: 〜たことがある・〜たり〜たり",structure:"V た + ことがある / V たり V たりする",overview:"V た + ことがある n\xf3i về kinh nghiệm đ\xe3 từng l\xe0m trong đời (kh\xf4ng n\xeau thời điểm cụ thể). 〜たり〜たりする liệt k\xea v\xe0i h\xe0nh động ti\xeau biểu trong nhiều h\xe0nh động, nhấn mạnh sự xen kẽ. Nhớ l\xe0 thể た chia giống thể て (て → た, で → だ).",examples:["富士山に登ったことがあります。[Fujisan ni nobotta koto ga arimasu] (T\xf4i đ\xe3 từng leo n\xfai Ph\xfa Sĩ.)","日曜日は洗濯したり、掃除したりします。[nichiyōbi wa sentaku shitari, sōji shitari shimasu] (Chủ nhật t\xf4i l\xfac th\xec giặt đồ, l\xfac th\xec dọn dẹp.)"],questions:[{prompt:"“T\xf4i đ\xe3 từng ăn sushi.” l\xe0:",options:["寿司を食べたことがあります。","寿司を食べることがあります。","寿司を食べますことがあります。"],answer:0,explanation:"Kinh nghiệm: V thể た + ことがあります."},{prompt:"Thể た của 「読む」 l\xe0:",options:["読んだ","読みた","読った"],answer:0,explanation:"む → んだ (giống 飲んで → 飲んだ)."},{prompt:"Chọn c\xe2u liệt k\xea đ\xfang:",options:["休みの日は寝たり、映画を見たりします。","休みの日は寝たり、映画を見ます。","休みの日は寝て、映画を見たりです。"],answer:0,explanation:"〜たり phải xuất hiện ở từng h\xe0nh động được liệt k\xea, kết th\xfac bằng する/します."}]},{id:"potential",level:"B1",title:"Thể khả năng: 〜ことができる・〜られる",structure:"V る + ことができる / Nh\xf3m 1: 〜e る   Nh\xf3m 2: 〜られる",overview:"C\xf3 hai c\xe1ch n\xf3i “c\xf3 thể l\xe0m”: V る + ことができる (trang trọng, dễ nhớ) v\xe0 thể khả năng của động từ. Nh\xf3m 1 đổi \xe2m cuối sang h\xe0ng え + る (書く → 書ける), nh\xf3m 2 th\xeam られる (食べる → 食べられる), する → できる, 来る → 来られる. Trợ từ đi k\xe8m thường đổi を → が.",examples:["私は漢字を書くことができます。[watashi wa kanji o kaku koto ga dekimasu] (T\xf4i c\xf3 thể viết chữ H\xe1n.)","日本語が話せます。[Nihongo ga hanasemasu] (T\xf4i n\xf3i được tiếng Nhật.)","辛い物は食べられません。[karai mono wa taberaremasen] (T\xf4i kh\xf4ng ăn được đồ cay.)"],questions:[{prompt:"Thể khả năng của 「読む」 l\xe0:",options:["読める","読まれる","読めれる"],answer:0,explanation:"Nh\xf3m 1: む → め + る."},{prompt:"Điền v\xe0o chỗ trống: 「納豆___食べられます。」(T\xf4i ăn được natto.)",options:["が","に","で"],answer:0,explanation:"Với thể khả năng, t\xe2n ngữ thường d\xf9ng が thay cho を."},{prompt:"Thể khả năng của 「する」 l\xe0:",options:["できる","される","しれる"],answer:0,explanation:"する → できる (bất quy tắc)."}]},{id:"conditionals",level:"B1",title:"C\xe2u điều kiện: 〜たら・〜ば・〜と・〜なら",structure:"V たら / V ば / V と / N・V なら",overview:"たら (nếu / sau khi) d\xf9ng rộng nhất, hợp mọi t\xecnh huống. ば nhấn điều kiện cần thiết. と diễn tả kết quả tất yếu (như quy luật tự nhi\xean, chỉ đường). なら d\xf9ng khi n\xeau đề t\xe0i người kia vừa n\xf3i để đưa lời khuy\xean. Với người học, h\xe3y ưu ti\xean たら trước.",examples:["雨が降ったら、家にいます。[ame ga futtara, ie ni imasu] (Nếu trời mưa th\xec t\xf4i ở nh\xe0.)","春になると、桜が咲きます。[haru ni naru to, sakura ga sakimasu] (Hễ đến m\xf9a xu\xe2n l\xe0 hoa anh đ\xe0o nở.)","京都へ行くなら、秋がいいですよ。[Kyōto e iku nara, aki ga ii desu yo] (Nếu đi Kyoto th\xec m\xf9a thu l\xe0 tốt đấy.)"],questions:[{prompt:"Điền v\xe0o chỗ trống: 「時間が___、手伝います。」(Nếu c\xf3 thời gian th\xec t\xf4i gi\xfap.)",options:["あったら","あるたら","ありたら"],answer:0,explanation:"たら gắn v\xe0o thể た: あった + ら."},{prompt:"「春になる___、暖かくなります。」 Chọn từ ph\xf9 hợp để diễn tả quy luật tự nhi\xean:",options:["と","たら","なら"],answer:0,explanation:"と diễn tả kết quả tất yếu, quy luật."},{prompt:"Thể ば của 「行く」 l\xe0:",options:["行けば","行くば","行きば"],answer:0,explanation:"Nh\xf3m 1: đổi \xe2m cuối sang h\xe0ng え rồi th\xeam ば: 行く → 行けば."}]},{id:"yoo-ni-tame-ni",level:"B1",title:"Mục đ\xedch: 〜ために・〜ように",structure:"V る + ために (\xfd ch\xed)   V る/ない + ように (khả năng, trạng th\xe1i)",overview:"Cả hai đều nghĩa “để ~”. ために đi với h\xe0nh động c\xf3 chủ \xfd của ch\xednh chủ ngữ, hai vế c\xf9ng chủ ngữ: 日本へ行くためにお金を貯めます. ように đi với động từ khả năng / phủ định / kh\xf4ng c\xf3 \xfd ch\xed, hoặc khi hai vế kh\xe1c chủ ngữ: 忘れないようにメモします.",examples:["日本で働くために、日本語を勉強しています。[Nihon de hataraku tame ni, Nihongo o benkyō shite imasu] (T\xf4i học tiếng Nhật để l\xe0m việc ở Nhật.)","忘れないように、メモを取ります。[wasurenai yō ni, memo o torimasu] (T\xf4i ghi ch\xfa để khỏi qu\xean.)"],questions:[{prompt:"Điền v\xe0o chỗ trống: 「遅れない___、早く出ます。」",options:["ように","ために","ことに"],answer:0,explanation:"Vế đầu l\xe0 phủ định / kh\xf4ng c\xf3 \xfd ch\xed → ように."},{prompt:"Điền v\xe0o chỗ trống: 「合格する___、毎日勉強します。」",options:["ために","ように","ばかりに"],answer:0,explanation:"H\xe0nh động c\xf3 chủ \xfd, c\xf9ng chủ ngữ → ために."},{prompt:"C\xe2u n\xe0o đ\xfang?",options:["日本語が話せるように、練習します。","日本語が話せるために、練習します。","日本語を話すように、練習するために。"],answer:0,explanation:"話せる l\xe0 thể khả năng → đi với ように."}]},{id:"keigo",level:"B2",title:"K\xednh ngữ v\xe0 khi\xeam nhường ngữ (敬語)",structure:"尊敬語: お〜になる / いらっしゃる   謙譲語: お〜する / 申す / 伺う",overview:"尊敬語 n\xe2ng cao người đối diện (kh\xe1ch h\xe0ng, cấp tr\xean): いる/行く/来る → いらっしゃる, 言う → おっしゃる, 食べる → 召し上がる. 謙譲語 hạ thấp bản th\xe2n: 行く/来る → 参る, 言う → 申す, 見る → 拝見する. Sai lầm hay gặp: d\xf9ng 尊敬語 cho ch\xednh m\xecnh hoặc người trong c\xf4ng ty khi n\xf3i với kh\xe1ch b\xean ngo\xe0i.",examples:["社長は今、会議室にいらっしゃいます。[shachō wa ima, kaigishitsu ni irasshaimasu] (Gi\xe1m đốc hiện đang ở ph\xf2ng họp.)","私が資料をお送りします。[watashi ga shiryō o ookuri shimasu] (Để t\xf4i gửi t\xe0i liệu cho ạ.)","田中と申します。[Tanaka to mōshimasu] (T\xf4i t\xean l\xe0 Tanaka.)"],questions:[{prompt:"Khi n\xf3i với kh\xe1ch h\xe0ng về gi\xe1m đốc của họ, “đang ăn” l\xe0:",options:["召し上がっています","いただいています","食べております"],answer:0,explanation:"召し上がる l\xe0 k\xednh ngữ của 食べる, d\xf9ng cho người được t\xf4n k\xednh."},{prompt:"Khi\xeam nhường ngữ của 「言う」 (t\xf4i n\xf3i) l\xe0:",options:["申す","おっしゃる","言われる"],answer:0,explanation:"申す l\xe0 khi\xeam nhường ngữ; おっしゃる l\xe0 k\xednh ngữ."},{prompt:"C\xe2u n\xe0o đ\xfang khi tự giới thiệu với kh\xe1ch?",options:["田中と申します。","田中でいらっしゃいます。","田中とおっしゃいます。"],answer:0,explanation:"Với bản th\xe2n lu\xf4n d\xf9ng 謙譲語: 申します."}]},{id:"wake-dewa-nai",level:"B2",title:"Diễn đạt tinh tế: 〜わけではない・〜わけにはいかない・〜ざるを得ない",structure:"普通形 + わけではない / V る + わけにはいかない / V ない(ず) + ざるを得ない",overview:"〜わけではない phủ định một phần (“kh\xf4ng c\xf3 nghĩa l\xe0 ~”). 〜わけにはいかない nghĩa l\xe0 “kh\xf4ng thể ~ v\xec l\xfd do x\xe3 hội, đạo l\xfd”. 〜ざるを得ない nghĩa l\xe0 “kh\xf4ng c\xf2n c\xe1ch n\xe0o kh\xe1c ngo\xe0i ~”. Đ\xe2y l\xe0 c\xe1c mẫu c\xe2u điển h\xecnh của N2, rất hay gặp trong email c\xf4ng việc v\xe0 b\xe0i đọc.",examples:["嫌いなわけではありませんが、あまり食べません。[kirai na wake dewa arimasen ga, amari tabemasen] (Kh\xf4ng phải l\xe0 gh\xe9t, chỉ l\xe0 \xedt ăn th\xf4i.)","明日は大事な会議があるので、休むわけにはいきません。[ashita wa daiji na kaigi ga aru node, yasumu wake ni wa ikimasen] (Mai c\xf3 cuộc họp quan trọng n\xean kh\xf4ng thể nghỉ được.)","上司の指示なので、従わざるを得ません。[jōshi no shiji na node, shitagawazaru o emasen] (V\xec l\xe0 chỉ thị của cấp tr\xean n\xean đ\xe0nh phải l\xe0m theo.)"],questions:[{prompt:"“Kh\xf4ng thể nghỉ được (v\xec tr\xe1ch nhiệm).” l\xe0:",options:["休むわけにはいかない。","休むわけではない。","休まざるを得る。"],answer:0,explanation:"〜わけにはいかない: kh\xf4ng thể l\xe0m v\xec l\xfd do đạo l\xfd, x\xe3 hội."},{prompt:"Dạng 〜ざるを得ない của 「する」 l\xe0:",options:["せざるを得ない","しざるを得ない","さざるを得ない"],answer:0,explanation:"する → せざるを得ない (bất quy tắc)."},{prompt:"「忙しいわけではありません。」 c\xf3 nghĩa gần nhất l\xe0:",options:["Kh\xf4ng hẳn l\xe0 bận.","Rất bận.","Chắc chắn bận."],answer:0,explanation:"〜わけではない phủ định một phần: “kh\xf4ng c\xf3 nghĩa l\xe0 ~”."}]}]}}}]);